css.doc-wf:
html, body { margin: 0; overflow-x: hidden; }
body { font-family: "Hanken Grotesk", sans-serif; background: #EDE6D8; }
.bar { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; padding: 14px 24px; font-size: 13px; color: #5C4B38; }
.bar .grow { flex: 1; }
.bar a { color: #B0542F; font-weight: 700; text-decoration: none; }
.bar a:hover { text-decoration: underline; }
.zoomctl { display: flex; align-items: center; gap: 6px; }
.zoomctl button { font: inherit; font-weight: 700; color: #5C4B38; background: #FFFCF5; border: 1px solid rgba(38,25,14,.18); border-radius: 99px; padding: 6px 14px; cursor: pointer; }
.zoomctl button[data-on="true"] { background: #26190E; color: #F7F1E6; border-color: #26190E; }
.zoomctl .pct { font-weight: 700; min-width: 42px; text-align: center; color: rgba(38,25,14,.55); }
.viewport { width: 100%; overflow: auto; padding-bottom: 40px; }
.fitbox { margin: 0 auto; }
.stage { width: 1580px; height: 880px; transform-origin: top left; }
.frame {
  position: relative; width: 1580px; height: 880px;
  background: #F7F1E6; border-radius: 18px; overflow: hidden;
  box-shadow: 0 2px 8px rgba(38,25,14,.08), 0 18px 50px rgba(38,25,14,.14);
  color: #26190E;
}
.node {
  position: absolute; background: #FFFCF5; border: 1.5px solid rgba(38,25,14,.18);
  border-radius: 12px; padding: 10px 12px; box-sizing: border-box;
}
.node h2 { margin: 0 0 4px; font-family: "Lora", serif; font-weight: 600; font-size: 15px; }
.node p { margin: 0 0 6px; font-size: 11.5px; line-height: 1.4; color: rgba(38,25,14,.62); }
.node .kicker { font-size: 9.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: rgba(38,25,14,.4); margin-bottom: 2px; }
.overlay { border-style: dashed; background: #FBF6EC; }
.tags { display: flex; flex-wrap: wrap; gap: 4px; }
.tag { font-size: 10px; font-weight: 700; border-radius: 99px; padding: 3px 8px; line-height: 1.2; }
.tag.green { background: #DCE8D4; color: #3D5A2E; }
.tag.amber { background: #F3E2C0; color: #7A5A16; }
.tag.exit { background: #EFE6D6; color: rgba(38,25,14,.55); }
svg.wires { position: absolute; inset: 0; pointer-events: none; }
svg.wires path, svg.wires line { fill: none; stroke: #A08D77; stroke-width: 2; }
svg.wires .dashed { stroke-dasharray: 6 5; }
.wire-label { position: absolute; font-size: 10px; font-weight: 700; color: #8A7A66; background: #F7F1E6; padding: 1px 5px; border-radius: 6px; z-index: 5; }
.titleblock { position: absolute; left: 28px; top: 22px; width: 600px; }
.titleblock h1 { margin: 0; font-family: "Lora", serif; font-weight: 600; font-size: 26px; }
.titleblock p { margin: 6px 0 0; font-size: 12.5px; line-height: 1.5; color: rgba(38,25,14,.62); }
.legend { position: absolute; right: 28px; top: 26px; display: flex; gap: 14px; align-items: center; font-size: 11.5px; color: rgba(38,25,14,.7); }
.legend .tag { font-size: 10px; }
.legend .dash { width: 26px; height: 0; border-top: 2px dashed #A08D77; display: inline-block; }
a { color: #B0542F; }

css.doc-ex:
:root { --paper:#F7F1E6; --surface:#FFFCF5; --sunken:#EFE6D6; --ink:#26190E; --ink2:rgba(38,25,14,.62); --ink3:rgba(38,25,14,.4); --line:rgba(38,25,14,.12); --accent:#C2492B; }
* { box-sizing: border-box; margin: 0; }
body { background: var(--paper); color: var(--ink); font-family: "Hanken Grotesk", sans-serif; -webkit-font-smoothing: antialiased; }
.page { max-width: 1060px; margin: 0 auto; padding: 56px 32px 96px; }
h1 { font-family: "Lora", serif; font-weight: 600; font-size: 44px; line-height: 1.05; }
h2 { font-family: "Lora", serif; font-weight: 600; font-size: 27px; margin: 70px 0 6px; }
h2 .k { color: var(--accent); margin-right: 10px; }
.sub { color: var(--ink2); font-size: 15px; line-height: 1.55; max-width: 720px; }
.rule { height: 1px; background: var(--line); margin: 18px 0 24px; }
.micro { font-size: 11px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--ink3); }
.opts { display: grid; grid-template-columns: repeat(auto-fit, minmax(228px, 1fr)); gap: 14px; }
.opt { background: var(--surface); border: 1px solid var(--line); border-radius: 16px; padding: 14px; display: flex; flex-direction: column; gap: 10px; }
.opt h3 { font-size: 15px; font-weight: 800; }
.opt .shipped { display: inline-block; font-size: 10px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; background: #DCE8D4; color: #3D5A2E; border-radius: 99px; padding: 3px 8px; margin-left: 6px; vertical-align: 2px; }
.opt ul { padding-left: 16px; font-size: 12.5px; line-height: 1.5; color: var(--ink2); }
.opt ul b { color: var(--ink); }
.mock { background: var(--paper); border: 1px solid var(--line); border-radius: 12px; padding: 8px; }
.mrow { display: flex; gap: 6px; }
.mcol { flex: 1; display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.ph { position: relative; border-radius: 9px; overflow: hidden; background: var(--sunken); }
.ph img { width: 100%; height: 100%; object-fit: cover; display: block; position: absolute; inset: 0; }
.ph .veil { position: absolute; inset: 0; background: linear-gradient(to top, rgba(12,7,3,.6), rgba(12,7,3,0) 55%); }
.ph .lab { position: absolute; left: 6px; bottom: 5px; color: #FFF7EB; font-size: 9px; font-weight: 700; }
.ph .chip { position: absolute; left: 5px; bottom: 5px; background: rgba(28,18,10,.5); color: #FFF9F0; font-size: 8.5px; font-weight: 700; border-radius: 99px; padding: 2px 6px; backdrop-filter: blur(4px); }
.under { font-size: 9.5px; font-weight: 700; padding: 1px 2px 3px; }
.under span { color: var(--ink3); font-weight: 600; }
.rec { display: flex; gap: 12px; align-items: flex-start; background: var(--surface); border: 1.5px solid var(--accent); border-radius: 16px; padding: 16px 18px; margin-top: 16px; }
.rec .badge { flex: none; background: var(--accent); color: #FFF6EC; font-size: 10px; font-weight: 800; letter-spacing: .07em; text-transform: uppercase; border-radius: 99px; padding: 4px 10px; margin-top: 1px; }
.rec p { font-size: 13.5px; line-height: 1.55; color: var(--ink2); }
.rec b { color: var(--ink); }
.flow { display: flex; flex-direction: column; gap: 5px; }
.step { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 600; }
.step .n { flex: none; width: 20px; height: 20px; border-radius: 99px; background: var(--sunken); display: flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 800; color: var(--ink2); }
.step .n.safe { background: var(--accent); color: #FFF6EC; }
.step .n.skip { background: transparent; border: 1.5px dashed var(--ink3); }
.step small { color: var(--ink3); font-weight: 600; }
.statcard { display: flex; align-items: center; gap: 10px; background: var(--sunken); border-radius: 14px; padding: 10px 12px; }
.ring { flex: none; width: 30px; height: 30px; border-radius: 99px; border: 3.5px solid var(--line); border-top-color: var(--accent); border-right-color: var(--accent); transform: rotate(45deg); }
.statcard .t { font-size: 12.5px; font-weight: 800; }
.statcard .s { font-size: 10.5px; color: var(--ink2); }
.btnrow { display: flex; gap: 6px; }
.b { flex: 1; display: flex; align-items: center; justify-content: center; min-height: 34px; border-radius: 99px; font-size: 11px; font-weight: 800; }
.b.p { background: var(--accent); color: #FFF6EC; }
.b.q { background: var(--sunken); }
.b.icon { flex: none; width: 34px; }
.b.dis { opacity: .4; }
a { color: var(--accent); font-weight: 700; text-decoration: none; }
table.meta { width: 100%; border-collapse: collapse; font-size: 12.5px; margin-top: 8px; }
table.meta td { padding: 7px 10px 7px 0; border-bottom: 1px solid var(--line); vertical-align: top; color: var(--ink2); }
table.meta td:first-child { font-weight: 800; color: var(--ink); width: 150px; }

css.doc-ds:
:root { --paper:#F7F1E6; --surface:#FFFCF5; --sunken:#EFE6D6; --ink:#26190E; --ink2:rgba(38,25,14,.62); --ink3:rgba(38,25,14,.4); --line:rgba(38,25,14,.12); --accent:#C2492B; --accent-ink:#FFF6EC; }
* { box-sizing: border-box; margin: 0; }
body { background: var(--paper); color: var(--ink); font-family: "Hanken Grotesk", sans-serif; -webkit-font-smoothing: antialiased; }
.page { max-width: 920px; margin: 0 auto; padding: 56px 32px 96px; }
h1 { font-family: "Lora", serif; font-weight: 600; font-size: 42px; line-height: 1.05; }
.sub { color: var(--ink2); font-size: 15px; line-height: 1.55; max-width: 640px; }
.comp { background: var(--surface); border: 1px solid var(--line); border-radius: 18px; padding: 20px; margin-top: 18px; display: grid; grid-template-columns: 300px 1fr; gap: 22px; }
.comp h2 { font-family: "Lora", serif; font-weight: 600; font-size: 20px; margin-bottom: 12px; grid-column: 1 / -1; }
.comp h2 .v { font-size: 11px; font-weight: 800; font-family: "Hanken Grotesk"; letter-spacing: .06em; color: #3D5A2E; background: #DCE8D4; border-radius: 99px; padding: 3px 9px; margin-left: 8px; vertical-align: 3px; }
.demo { background: var(--paper); border: 1px solid var(--line); border-radius: 14px; padding: 14px; display: flex; flex-direction: column; gap: 10px; align-items: flex-start; }
.demo .cap { font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ink3); }
.notes { font-size: 13px; line-height: 1.55; color: var(--ink2); }
.notes b { color: var(--ink); }
.notes .a11y { display: block; margin-top: 10px; padding: 9px 12px; background: var(--sunken); border-radius: 10px; font-size: 12.5px; }
.notes .a11y::before { content: "Accessibility — "; font-weight: 800; color: var(--ink); }
.notes .copy { display: block; margin-top: 8px; font-size: 12.5px; }
.notes .copy::before { content: "Content — "; font-weight: 800; color: var(--ink); }
/* live component styles (mirrors app/styles.css) */
.chip { display: inline-flex; align-items: center; gap: 6px; border-radius: 999px; border: 1.5px solid var(--line); background: var(--surface); padding: 9px 16px; font-size: 14px; font-weight: 600; min-height: 40px; }
.chip.on { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.chip.al-on { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); font-weight: 700; }
.warnchip { display: inline-flex; align-items: center; gap: 5px; background: var(--accent); color: var(--accent-ink); border-radius: 999px; padding: 5px 10px; font-size: 11.5px; font-weight: 800; }
.banner { display: flex; gap: 10px; align-items: flex-start; background: rgba(194,73,43,.10); border: 1.5px solid var(--accent); border-radius: 16px; padding: 12px 14px; }
.banner .x { color: var(--accent); flex: none; font-weight: 900; font-size: 13px; width: 20px; height: 20px; border-radius: 99px; border: 2px solid var(--accent); display: flex; align-items: center; justify-content: center; }
.banner .t { font-size: 13.5px; font-weight: 800; color: var(--accent); }
.banner .s { font-size: 12px; color: var(--ink2); line-height: 1.45; }
.stat { display: flex; align-items: center; gap: 10px; background: var(--sunken); border-radius: 14px; padding: 11px 13px; width: 100%; }
.stat .t { font-size: 13.5px; font-weight: 800; }
.stat .s { font-size: 11.5px; color: var(--ink2); }
.stat .s .link { color: var(--accent); font-weight: 800; }
.stat.new { background: transparent; border: 1.5px dashed var(--ink3); }
.statuspill { display: inline-flex; border-radius: 99px; background: var(--ink); color: var(--paper); padding: 6px 12px; font-size: 12px; font-weight: 700; }
.glasspill { display: inline-flex; border-radius: 99px; background: rgba(120,36,22,.75); color: #FFF9F0; padding: 6px 12px; font-size: 12px; font-weight: 700; }
.skel { border-radius: 12px; background: linear-gradient(100deg, var(--sunken) 40%, rgba(255,255,255,.5) 50%, var(--sunken) 60%); background-size: 200% 100%; animation: sh 1.4s linear infinite; }
@keyframes sh { from { background-position: 200% 0; } to { background-position: -200% 0; } }
@media (prefers-reduced-motion: reduce) { .skel { animation: none; } }
.obanner { display: flex; gap: 10px; align-items: center; background: var(--sunken); border: 1px solid var(--line); border-radius: 14px; padding: 10px 13px; width: 100%; }
.btn { display: inline-flex; align-items: center; justify-content: center; border-radius: 99px; min-height: 44px; padding: 0 20px; font-weight: 700; font-size: 14px; }
.btn.p { background: var(--accent); color: var(--accent-ink); }
.btn.q { background: var(--sunken); }
.btn.dis { opacity: .35; }
.focusdemo { outline: 2.5px solid var(--accent); outline-offset: 2px; border-radius: 8px; }
a { color: var(--accent); font-weight: 700; text-decoration: none; }
@media (max-width: 720px) { .comp { grid-template-columns: 1fr; } }

css.doc-tp:
:root { --paper:#F7F1E6; --surface:#FFFCF5; --sunken:#EFE6D6; --ink:#26190E; --ink2:rgba(38,25,14,.62); --ink3:rgba(38,25,14,.4); --line:rgba(38,25,14,.12); --accent:#C2492B; }
* { box-sizing: border-box; margin: 0; }
body { background: var(--paper); color: var(--ink); font-family: "Hanken Grotesk", sans-serif; -webkit-font-smoothing: antialiased; }
.page { max-width: 880px; margin: 0 auto; padding: 56px 32px 96px; }
h1 { font-family: "Lora", serif; font-weight: 600; font-size: 42px; line-height: 1.05; }
h2 { font-family: "Lora", serif; font-weight: 600; font-size: 25px; margin: 56px 0 6px; }
.sub { color: var(--ink2); font-size: 15px; line-height: 1.55; max-width: 640px; }
.rule { height: 1px; background: var(--line); margin: 16px 0 20px; }
table { width: 100%; border-collapse: collapse; font-size: 13px; }
th { text-align: left; font-size: 10.5px; font-weight: 800; letter-spacing: .07em; text-transform: uppercase; color: var(--ink3); padding: 8px 10px 8px 0; border-bottom: 1.5px solid var(--line); }
td { padding: 9px 10px 9px 0; border-bottom: 1px solid var(--line); vertical-align: top; line-height: 1.45; color: var(--ink2); }
td:first-child { font-weight: 800; color: var(--ink); white-space: nowrap; }
.card { background: var(--surface); border: 1px solid var(--line); border-radius: 16px; padding: 18px 20px; margin-top: 14px; }
.card h3 { font-size: 15px; font-weight: 800; margin-bottom: 8px; }
.card p, .card li { font-size: 13.5px; line-height: 1.55; color: var(--ink2); }
.card ul, .card ol { padding-left: 18px; }
.card b { color: var(--ink); }
.q { font-style: italic; }
.tag { display: inline-block; font-size: 10px; font-weight: 800; border-radius: 99px; padding: 2px 8px; background: var(--sunken); color: var(--ink2); margin-left: 6px; vertical-align: 1px; white-space: nowrap; }
.sev { display: inline-block; width: 10px; height: 10px; border-radius: 99px; margin-right: 6px; vertical-align: -1px; }
a { color: var(--accent); font-weight: 700; text-decoration: none; }
a:hover { text-decoration: underline; }
.note { background: var(--sunken); border-radius: 12px; padding: 10px 14px; font-size: 12.5px; color: var(--ink2); margin-top: 14px; }
/* wide protocol tables scroll inside their own box on narrow screens */
@media (max-width: 640px) {
  table { display: block; overflow-x: auto; -webkit-overflow-scrolling: touch; }
}
